<?php $plural=$domain==='career'?'careers':'bursaries';?><a href="<?=e(url('/'.$plural))?>">← Back to opportunities</a><article class="card shadow-sm mt-3"><div class="card-body p-4"><span class="badge text-bg-<?=$opportunity['status']==='published'?'success':'secondary'?>"><?=e($opportunity['status'])?></span><h1 class="mt-2"><?=e($opportunity['title'])?></h1><p class="lead"><?=e($domain==='career'?$opportunity['organisation']:$opportunity['provider'])?></p><?php if($domain==='career'):?><p><?=nl2br(e($opportunity['description']))?></p><h2 class="h4">Requirements</h2><p><?=nl2br(e($opportunity['requirements']))?></p><p><strong>Employment:</strong> <?=e($opportunity['employment_type'])?> · <?=e($opportunity['location']?:'Location flexible')?></p><?php else:?><h2 class="h4">Field and level</h2><p><?=e($opportunity['field_of_study'].' · '.$opportunity['study_level'])?></p><p><?=nl2br(e($opportunity['description']))?></p><h2 class="h4">Eligibility</h2><p><?=nl2br(e($opportunity['eligibility_criteria']))?></p><h2 class="h4">Benefits</h2><p><?=nl2br(e($opportunity['benefits']))?></p><?php endif;?><p><strong>Closing date:</strong> <?=e($opportunity['closing_date'])?></p><?php if($opportunity['status']==='published'&&$opportunity['closing_date']>=date('Y-m-d')):?><?php if(user()):?><a class="btn btn-primary" href="<?=e(url('/'.$plural.'/'.$opportunity['opportunity_reference'].'/apply'))?>"><?=$application?'View or continue application':'Apply'?></a><?php else:?><a class="btn btn-primary" href="<?=e(url('/login'))?>">Log in to apply</a> <a class="btn btn-outline-primary" href="<?=e(url('/register'))?>">Register</a><?php endif;?><?php else:?><div class="alert alert-secondary">Applications are closed.</div><?php endif;?><p class="small text-muted mt-3"><?=$domain==='career'?'An application does not guarantee employment.':'An approved application does not mean funds have been disbursed.'?></p></div></article>
